"""Loader for data/lifestyle/exercises.csv (generated by
scripts/convert_datasets.py; schema in data/lifestyle/schema.md). Tolerant of
an empty or missing file."""

import csv
from dataclasses import dataclass, field
from pathlib import Path

from src.core.config import DATA_DIR

EXERCISES_CSV = DATA_DIR / "lifestyle" / "exercises.csv"

CATEGORIES = ("aerobic", "strength", "flexibility", "balance", "breathing")
# the categories the prescription plans, in the order it lists them
PLAN_GROUPS = ("aerobic", "strength", "flexibility", "balance")
FITNESS_LEVELS = ("beginner", "intermediate", "advanced")
INTENSITY_LEVELS = ("light", "moderate", "vigorous")
# the conditions the dataset rates each exercise for: keys of
# data/reference/contraindications.yaml
RATED_CONDITIONS = ("pregnancy", "hypertension", "diabetes", "anemia", "knee_osteoarthritis")
CONTRA_TAGS = frozenset(
    {f"avoid_{c}" for c in RATED_CONDITIONS}
    | {"supine_position", "not_for_older_adults", "female_only", "male_only"}
)
TRAITS = frozenset({
    "pelvic_floor", "pregnancy_recommended", "knee_oa_strengthening", "high_impact",
    "low_impact", "post_meal", "isometric_hold", "falls_prevention", "seated",
})


def _split(cell: str | None) -> tuple:
    return tuple(t.strip() for t in (cell or "").split("|") if t.strip())


@dataclass(frozen=True)
class Exercise:
    exercise_id: str
    name_en: str
    name_bn: str
    category: str          # one of CATEGORIES
    met_value: float | None
    equipment: str
    intensity_level: str   # light | moderate | vigorous, "" without a MET
    tags: tuple = field(default_factory=tuple)  # contra_tags: checked by the gate
    source: str = ""
    exercise_type: str = ""
    body_region: str = ""
    muscles: str = ""
    fitness_level: str = "beginner"
    needs_equipment: bool = False
    setting: str = "home or gym"
    sex: str = "both"
    older_adult: str = "yes"     # yes | modify | no
    traits: tuple = field(default_factory=tuple)
    modify_for: tuple = field(default_factory=tuple)
    notes: dict = field(default_factory=dict)  # "general" and condition key -> note
    injury_avoid: tuple = field(default_factory=tuple)
    injury_modify: tuple = field(default_factory=tuple)
    dose: str = ""
    how_to: str = ""
    easier_version: str = ""
    safety_notes: str = ""
    source_url: str = ""
    source_detail: str = ""
    evidence_basis: str = ""
    video_url: str = ""
    video_title: str = ""
    video_channel: str = ""
    video_match: str = "none"

    def __hash__(self) -> int:  # notes is a dict; an exercise is its id
        return hash(self.exercise_id)

    @property
    def home_feasible(self) -> bool:
        return "home" in self.setting

    @property
    def level_rank(self) -> int:
        return FITNESS_LEVELS.index(self.fitness_level)


def load_exercises(path: Path | None = None) -> list[Exercise]:
    path = path or EXERCISES_CSV
    if not path.exists():
        return []
    exercises: list[Exercise] = []
    with open(path, encoding="utf-8-sig", newline="") as f:
        for row in csv.DictReader(f):
            if not (row.get("exercise_id") or "").strip():
                continue
            met = (row.get("met_value") or "").strip()
            notes = {"general": (row.get("note_general") or "").strip()}
            for condition in RATED_CONDITIONS:
                notes[condition] = (row.get(f"note_{condition}") or "").strip()
            exercises.append(Exercise(
                exercise_id=row["exercise_id"].strip(),
                name_en=row["name_en"].strip(),
                name_bn=(row.get("name_bn") or "").strip(),
                category=(row.get("category") or "aerobic").strip(),
                met_value=float(met) if met else None,
                equipment=(row.get("equipment") or "none (bodyweight)").strip(),
                intensity_level=(row.get("intensity_level") or "").strip(),
                tags=_split(row.get("contra_tags")),
                source=(row.get("source") or "").strip(),
                exercise_type=(row.get("exercise_type") or "").strip(),
                body_region=(row.get("body_region") or "").strip(),
                muscles=(row.get("muscles") or "").strip(),
                fitness_level=(row.get("fitness_level") or "beginner").strip(),
                needs_equipment=(row.get("needs_equipment") or "").strip() == "yes",
                setting=(row.get("setting") or "home or gym").strip(),
                sex=(row.get("sex") or "both").strip(),
                older_adult=(row.get("older_adult") or "yes").strip(),
                traits=_split(row.get("traits")),
                modify_for=_split(row.get("modify_for")),
                notes=notes,
                injury_avoid=_split(row.get("injury_avoid")),
                injury_modify=_split(row.get("injury_modify")),
                dose=(row.get("dose") or "").strip(),
                how_to=(row.get("how_to") or "").strip(),
                easier_version=(row.get("easier_version") or "").strip(),
                safety_notes=(row.get("safety_notes") or "").strip(),
                source_url=(row.get("source_url") or "").strip(),
                source_detail=(row.get("source_detail") or "").strip(),
                evidence_basis=(row.get("evidence_basis") or "").strip(),
                video_url=(row.get("video_url") or "").strip(),
                video_title=(row.get("video_title") or "").strip(),
                video_channel=(row.get("video_channel") or "").strip(),
                video_match=(row.get("video_match") or "none").strip(),
            ))
    return exercises
